import { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over';

interface Project {
  id: string;
  name: string;
  quotaUsed: number;
  quotaMax: number;
  status: ProjectStatus;
}

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Атлас', quotaUsed: 42, quotaMax: 100, status: 'active' },
  { id: 'p2', name: 'Компас', quotaUsed: 88, quotaMax: 100, status: 'active' },
  { id: 'p3', name: 'Маршрут', quotaUsed: 15, quotaMax: 100, status: 'paused' },
  { id: 'p4', name: 'Горизонт', quotaUsed: 100, quotaMax: 100, status: 'over' },
  { id: 'p5', name: 'Ориентир', quotaUsed: 63, quotaMax: 100, status: 'active' },
  { id: 'p6', name: 'Периметр', quotaUsed: 30, quotaMax: 100, status: 'paused' },
  { id: 'p7', name: 'Вектор', quotaUsed: 95, quotaMax: 100, status: 'over' },
  { id: 'p8', name: 'Контур', quotaUsed: 20, quotaMax: 100, status: 'active' },
  { id: 'p9', name: 'Плато', quotaUsed: 55, quotaMax: 100, status: 'paused' },
  { id: 'p10', name: 'Меридиан', quotaUsed: 10, quotaMax: 100, status: 'active' },
  { id: 'p11', name: 'Радиус', quotaUsed: 78, quotaMax: 100, status: 'over' },
  { id: 'p12', name: 'Ландшафт', quotaUsed: 5, quotaMax: 100, status: 'paused' },
];

const STATUS_LABEL: Record<ProjectStatus, string> = {
  active: 'Активен',
  paused: 'На паузе',
  over: 'Превышена квота',
};

const STATUS_TONE: Record<ProjectStatus, 'success' | 'warning' | 'danger'> = {
  active: 'success',
  paused: 'warning',
  over: 'danger',
};

const STATUS_FILTERS: ProjectStatus[] = ['active', 'paused', 'over'];

const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>(STATUS_FILTERS);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(STATUS_FILTERS);
    setPage(1);
  };

  const filtered = useMemo(
    () => PROJECTS.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const safePage = Math.min(page, pageCount);
  const visible = filtered.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE);

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        maxWidth: 560,
        padding: '20px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
      }}
    >
      <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
        {STATUS_FILTERS.map((status) => (
          <JxChip
            key={status}
            active={activeStatuses.includes(status)}
            removable={activeStatuses.includes(status)}
            onRemove={() => toggleStatus(status)}
            onClick={() => {
              if (!activeStatuses.includes(status)) toggleStatus(status);
            }}
          >
            {STATUS_LABEL[status]}
          </JxChip>
        ))}
      </div>

      {filtered.length === 0 ? (
        <JxEmptyState
          title="Проекты не найдены"
          message="Под текущие фильтры ничего не подошло."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
            {visible.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '16px',
                  padding: '12px',
                  borderBottom: '1px solid var(--jx-rule)',
                }}
              >
                <JxProgressCircle
                  value={project.quotaUsed}
                  max={project.quotaMax}
                  showValue
                />
                <span
                  style={{
                    flex: 1,
                    color: 'var(--jx-text)',
                    fontFamily: 'var(--jx-font-sans)',
                  }}
                >
                  {project.name}
                </span>
                <JxBadge tone={STATUS_TONE[project.status]} dot>
                  {STATUS_LABEL[project.status]}
                </JxBadge>
              </div>
            ))}
          </div>

          <JxPagination total={pageCount} page={safePage} onPageChange={setPage} />
        </>
      )}
    </div>
  );
}

